const d=$json;
const email=String(d.normalizedEmail||'').trim().toLowerCase();
const emailValid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const budgetRaw=d.budget;
const budget=budgetRaw===''||budgetRaw==null?null:Number(budgetRaw);
const missing=[];
if(!String(d.name||'').trim()) missing.push('name');
if(!emailValid) missing.push('valid work email');
if(!String(d.normalizedCompany||'').trim()) missing.push('company');
if(!String(d.need||'').trim()) missing.push('business need');
if(!['B2B professional services','Accounting / finance','Software / SaaS','Real estate','Recruitment','Marketing agency','Other (non-target industry)','Not sure yet'].includes(String(d.companyType||'').trim())) missing.push('industry / company profile');
if(!['Website','Advertisement','Referral','Inbound call','Landing page','Other'].includes(String(d.leadSource||'').trim())) missing.push('lead source');
if(!['0-30 days','31-90 days','3-6 months','6+ months','Not sure yet'].includes(String(d.timeline||'').trim())) missing.push('purchase timeline');
if(!['Decision-maker','Influencer / working with decision-maker','Researching only','Not sure'].includes(String(d.decisionMaker||'').trim())) missing.push('decision-making role');
if(!['Yes - reply to my enquiry','No - do not contact me'].includes(String(d.consentStatus||'').trim())) missing.push('contact consent choice');
if(budget!==null&&(!Number.isFinite(budget)||budget<0)) missing.push('valid non-negative budget');
const optOutOnly=String(d.consentStatus||'')==='No - do not contact me'&&emailValid;
const valid=missing.length===0||optOutOnly;
const normalizedBudget=budget!==null&&Number.isFinite(budget)&&budget>=0?budget:null;
const validationStatus=optOutOnly?(missing.length?'OPT_OUT_SUPPRESSION_ONLY':'OPT_OUT_SUPPRESSION'):(valid?'VALID':'NEEDS_CORRECTION');
return {json:{...d,normalizedEmail:email,budget:normalizedBudget,valid,missingFields:missing,validationStatus,suppressionOnly:optOutOnly}};

const d=$json;
const score=Number(d.leadScore||0);
const eventKey=String(d.sourceEventId||'')+':'+String(d.routeOutcome||'QUALIFIED');
return {json:{...d,recordStatus:'QUALIFICATION_RECORDED',auditEvent:{eventType:'lead_qualification',eventAt:new Date().toISOString(),eventKey,leadEmail:d.normalizedEmail||'',detail:'score='+score+'; route='+String(d.routeOutcome||'REVIEW')+'; idempotency='+String(d.idempotencyKey||'')},productionReadiness:'CRM_CALENDAR_MESSAGING_REQUIRE_CREDENTIALS',handoffSummary:String(d.priority||'REVIEW')+' lead · score '+String(d.leadScore??'unknown')+'/100 · '+String(d.qualificationStatus||d.validationStatus||'review')+' · next: '+String(d.nextAction||'manual review')}};

const d=$json;
const industry=String(d.companyType||'').toLowerCase();
const needText=String(d.need||'').trim();
const need=needText.toLowerCase();
const timeline=String(d.timeline||'');
const authority=String(d.decisionMaker||'');
const budget=Number(d.budget);
const budgetKnown=d.budget!==null&&d.budget!==undefined&&String(d.budget).trim()!==''&&Number.isFinite(budget)&&budget>=0;
const fitKnown=!!industry&&!/not sure/i.test(industry);
const fitScore=!fitKnown?0:(/b2b professional services|accounting|finance|software|saas|real estate|recruitment|marketing agency/.test(industry)?25:0);
const hasTask=/invoice|reconcil|lead|crm|workflow|customer|support|recruit|booking|appointment|report|spreadsheet|email|account|document|onboard|data entry|sales|candidate|property|listing|case|ticket|approval|intake|finance|marketing/i.test(need);
const hasPain=/manual|spreadsheet|inbox|email|repetitive|duplicate|delay|slow|error|bottleneck|follow.?up|missed|time.?consuming|currently|staff|team spends|handoff|disconnected|pain|problem|struggle|hard to|difficult|too much work/i.test(need);
const hasOutcome=/automate|automation|reduce|improve|increase|save time|streamline|faster|efficient|accuracy|report|scale|cut cost|fewer steps|less manual|reconcile|route|centralize|visibility/i.test(need);
const needScore=!needText?0:(hasTask&&hasPain&&hasOutcome?25:(hasTask&&(hasPain||hasOutcome)?20:((hasTask||hasPain||hasOutcome)?10:5)));
const timelineScore=/0-30 days/.test(timeline)?20:/31-90 days/.test(timeline)?15:/3-6 months/.test(timeline)?8:/6\+ months/.test(timeline)?3:0;
const authorityScore=/influencer|working with decision-maker/i.test(authority)?10:/decision-maker/i.test(authority)?15:/researching/i.test(authority)?4:0;
const budgetScore=!budgetKnown?0:budget>=5000?15:budget>=2000?10:budget>0?5:0;
const unknowns=[];
if(!budgetKnown) unknowns.push('budget');
if(/not sure/i.test(timeline)) unknowns.push('purchase timeline');
if(/not sure/i.test(authority)) unknowns.push('decision authority');
if(!fitKnown) unknowns.push('target industry / company profile');
if(!hasTask||!hasOutcome) unknowns.push('clear business problem / desired outcome');
const leadScore=fitScore+needScore+timelineScore+authorityScore+budgetScore;
const consent=String(d.consentStatus||'')==='Yes - reply to my enquiry';
const priority=leadScore>=70?'HOT':leadScore>=40?'WARM':'NURTURE';
const qualificationStatus=!consent?'SUPPRESSED_NO_CONSENT':unknowns.length?'NEEDS_QUALIFICATION':leadScore>=70?'MEETING_ELIGIBLE':leadScore>=40?'DISCOVERY_RECOMMENDED':'NURTURE_OR_REVIEW';
const nextAction=!consent?'SUPPRESS_OUTREACH_AND_STORE_OPT_OUT':unknowns.length?'ASK_QUALIFYING_QUESTIONS: '+unknowns.join(', '):leadScore>=70?'ELIGIBLE_FOR_HUMAN_APPROVED_MEETING_OFFER':leadScore>=40?'PERSONALIZED_DISCOVERY_OR_CLARIFY':'LOW_PRIORITY_NURTURE_OR_REVIEW';
const scoreEvidence=['fit='+fitScore+'/25; industry='+String(d.companyType||'UNKNOWN')+'; profileKnown='+fitKnown,'need='+needScore+'/25; taskSignal='+hasTask+'; painSignal='+hasPain+'; outcomeSignal='+hasOutcome+'; evidence='+needText.slice(0,180),'timeline='+timelineScore+'/20; value='+timeline,'authority='+authorityScore+'/15; value='+authority,'budget='+budgetScore+'/15; value='+(budgetKnown?budget:'UNKNOWN')].join(' | ');
const firstName=String(d.name||'').trim().split(/\s+/)[0]||'there';
const needDescription=String(d.need||'your automation goal').trim().replace(/[.!?]+$/,'').slice(0,220);
const outreachDraft=consent?'Hi '+firstName+',\n\nThanks for reaching out about '+needDescription+'. A short discovery conversation may help us understand your current process, constraints and desired outcome.\n\nBefore recommending a solution, could you share '+(unknowns.length?unknowns.join(' and '):'whether you would like to review available times for a discovery call')+'?\n\nBest,\nThe team':'';
return {json:{...d,fitScore,needScore,timelineScore,authorityScore,budgetScore,leadScore,priority,qualificationStatus,unknownFields:unknowns,scoreEvidence,nextAction,outreachDraft,consentGranted:consent,scoreModelVersion:'B2B-100-v2',scoredAt:new Date().toISOString(),meetingStatus:'NOT_BOOKED',crmSyncStatus:'NOT_CONNECTED'}};

const lead=$('03 - Score Qualification Components').item.json;
const response=$json;
let structured=response.output && typeof response.output === 'object' ? response.output : null;
if (!structured) {
 const raw=String(response.output||response.text||response.output_text||response.response?.output_text||'').trim();
 try { structured=JSON.parse(raw); } catch { structured={outreachDraft:raw}; }
}
const candidate=String(structured.outreachDraft||'').trim();
const usable=candidate.length>20&&!response.error;
const pains=Array.isArray(structured.painPoints)?structured.painPoints:[];
const questions=Array.isArray(structured.followUpQuestions)?structured.followUpQuestions:[];
return {json:{
 ...lead,
 aiNeedCategory:String(structured.needCategory||''),
 aiProblemSummary:String(structured.problemSummary||''),
 aiPainPoints:JSON.stringify(pains),
 aiDesiredOutcome:String(structured.desiredOutcome||''),
 aiFollowUpQuestions:JSON.stringify(questions),
 outreachDraft:usable?candidate:lead.outreachDraft,
 aiDraftStatus:usable&&structured.needCategory&&structured.problemSummary?'AI_ENRICHMENT_AND_DRAFT_READY':usable?'AI_DRAFT_READY':'TEMPLATE_FALLBACK',
 aiDraftReviewed:false
}};

const lead = $('10 - Configure Business Connectors').item.json;
const event = $json || {};
const provider = String(lead.calendarProvider || 'unknown');
const eventId = String(event.id || '');
const eventUrl = String(event.htmlLink || event.webLink || '');
const label = String(event.summary || event.subject || 'Discovery call');
const eventKey = String(lead.sourceEventId || lead.idempotencyKey || '') + ':calendar:booked:' + provider + ':' + eventId;
return {json:{...lead,calendarProvider:provider,calendarStatus:'BOOKED',calendarEventId:eventId,calendarEventUrl:eventUrl,meetingStatus:'BOOKED',auditEvent:{eventKey,eventType:'calendar_booking',eventStatus:'BOOKED',leadEmail:lead.normalizedEmail||'',detail:provider+' meeting booked: '+label+'; eventId='+eventId+'; url='+eventUrl,eventAt:new Date().toISOString()}}};

const lead = $('10 - Configure Business Connectors').item.json;
const input = $json || {};
const available = typeof input.available === 'boolean' ? input.available : input.calendarAvailable === true;
const provider = String(lead.calendarProvider || 'unknown');
const status = !available ? 'SLOT_UNAVAILABLE' : (lead.bookingConsent === 'Book this exact slot if available' ? 'AVAILABLE_NOT_BOOKED' : 'AVAILABLE_AWAITING_SLOT_SELECTION');
const detail = provider+' availability check: '+status+'; requestedStart='+String(lead.requestedStart||'')+'; requestedEnd='+String(lead.requestedEnd||'')+'; overlappingEvents='+String(input.overlappingEventCount ?? 'not returned');
const eventKey = String(lead.sourceEventId || lead.idempotencyKey || '')+':calendar-check:'+provider+':'+new Date().toISOString();
return {json:{...lead,calendarProvider:provider,calendarStatus:status,calendarEventId:'',meetingStatus:'NOT_BOOKED',auditEvent:{eventKey,eventType:'calendar_availability_check',eventStatus:status,leadEmail:lead.normalizedEmail||'',detail,eventAt:new Date().toISOString()}}};

const lead = $('10 - Configure Business Connectors').first().json;
const start = Date.parse(lead.requestedStart || '');
const end = Date.parse(lead.requestedEnd || '');
const events = $input.all().map(item => item.json || {}).filter(event => event.start || event.end);
const overlapping = events.filter(event => {
  if (event.isCancelled === true || String(event.showAs || 'busy').toLowerCase() === 'free') return false;
  const eventStart = Date.parse(event.start?.dateTime || event.start || '');
  const eventEnd = Date.parse(event.end?.dateTime || event.end || '');
  return Number.isFinite(eventStart) && Number.isFinite(eventEnd) && eventStart < end && eventEnd > start;
});
const validWindow = Number.isFinite(start) && Number.isFinite(end) && end > start;
const available = validWindow && overlapping.length === 0;
return [{json:{...lead,calendarAvailable:available,calendarCheckStatus:!validWindow?'INVALID_SLOT':available?'AVAILABLE':'UNAVAILABLE',overlappingEventCount:overlapping.length,calendarCheckedAt:new Date().toISOString()}}];
